    private static boolean hasOwnToString(fortress.AnyType.Any a) {
        try {
            Class<?> d = a.getClass().getMethod("toString").getDeclaringClass();
            return d != FValue.class && d != Object.class;
        } catch (NoSuchMethodException e) {
            return false;
